const content=document.querySelector('#content'),dialog=document.querySelector('#dialog');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=v=>v?new Date(v).toLocaleString('pt-BR'):'—';
let branding={name:'WhatsApp API'},managedUsers=[];
let user,instance,tab='connection',sequence=0,pollTimer,toastTimer;
let activityViews={global:{page:1,filters:{}},instance:{page:1,filters:{}}},activitySequence={global:0,instance:0};
let incidentFilters={instance_id:'',status:'all',email_status:'all',from:'',to:'',kind:'confirmed'},incidentPage=1,historyRequest=0,detailRequest=0;
const api=async(path,options={})=>{const r=await fetch(path,{...options,headers:{'Content-Type':'application/json','X-Requested-With':'wa-platform',...options.headers}});const data=await r.json();if(!r.ok){const e=new Error(data.message||'Não foi possível concluir.');e.status=r.status;throw e;}return data;};
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),6000);}
function title(k,h,p,a=''){return `<div class="page-head"><div><div class="eyebrow">${k}</div><h1>${h}</h1><p>${p}</p></div>${a}</div>`;}
const newButton='<button class="primary" data-action="new">＋ Nova instância</button>';
const labels={disabled:'Desativada',authenticated:'Conectada',disconnected:'Desconectada',initialize:'Inicializando',qr:'Aguardando leitura',retrying:'Reconectando',disconnecting:'Desconectando',queue:'Na fila',sending:'Enviando',sent:'Enviada',unsent:'Não enviada',unknown:'Sem confirmação',received:'Recebida'};
const badge=s=>`<span class="badge ${['authenticated','sent','received'].includes(s)?'green':['qr','queue','retrying','sending'].includes(s)?'amber':''}">${esc(labels[s]||s)}</span>`;
function rows(items,{disabled=false}={}){return items.length?`<div class="table-wrap"><table><thead><tr><th>Instância</th>${user.role==='admin'?'<th>Usuário</th>':''}<th>Número</th><th>Conexão</th><th>Mensagens</th><th></th></tr></thead><tbody>${[...items].sort((a,b)=>Number(Boolean(b.connection_alert))-Number(Boolean(a.connection_alert))).map(i=>`<tr class="${i.connection_alert?'instance-danger':''}"><td><span class="cell-name">${esc(i.name)}</span><span class="cell-sub">instance${esc(i.id)}</span></td>${user.role==='admin'?`<td>${esc(i.owner_name)}</td>`:''}<td>${esc(i.phone||'Ainda não conectado')}</td><td>${i.connection_alert?'<span class="badge red">⚠ Conexão perdida</span><br>':''}${badge(i.status)}</td><td>${i.message_counts.total}</td><td><a href="#instance/${i.id}">Gerenciar ↗</a></td></tr>`).join('')}</tbody></table></div>`:disabled?'<div class="empty"><div class="empty-icon">▣</div><h3>Nenhuma instância desativada</h3><p>As instâncias desativadas ficam aqui, com seus dados e histórico preservados.</p></div>':`<div class="empty"><div class="empty-icon">▣</div><h3>Conecte seu primeiro WhatsApp</h3><p>Crie uma instância, leia o QR Code pelo celular e use as credenciais no seu sistema.</p>${newButton}</div>`;}
function login(){clearTimeout(pollTimer);user=null;instance=null;dialog.close();document.body.classList.add('signed-out');content.innerHTML=`<section class="login-panel"><a class="brand login-brand" href="#" data-brand="positive"></a><div class="eyebrow">BEM-VINDO AO SEU WORKSPACE</div><h1>Acesse suas conexões.</h1><p>Entre para gerenciar suas instâncias do WhatsApp.</p><form id="login-form" class="fields"><label>E-mail<input name="email" type="email" autocomplete="username" required autofocus></label><label>Senha<input name="password" type="password" autocomplete="current-password" required maxlength="256"></label><p id="login-error" class="error" role="alert"></p><button class="primary">Entrar no painel →</button></form><p class="login-note">Ainda não tem acesso? Solicite uma conta ao administrador.</p></section>`;applyBranding();}
async function start(){try{branding=(await api('/api/branding')).branding;applyBranding();user=(await api('/api/auth/me')).user;document.body.classList.remove('signed-out');document.querySelector('#account-name').textContent=user.name;document.querySelector('#users-nav').hidden=user.role!=='admin';document.querySelector('#general-admin-nav').hidden=user.role!=='admin';await render();}catch(e){if(e.status===401)login();else content.innerHTML=`<p class="error">${esc(e.message)}</p>`;}}
async function render(){if(!user)return;clearTimeout(pollTimer);const seq=++sequence;const route=location.hash.slice(1)||'dashboard',key=route.split('/')[0];document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===(key==='instance'?'instances':key==='branding'?'users':key)));document.querySelector('#breadcrumb').textContent=({dashboard:'Visão geral',instances:'Instâncias',instance:'Detalhes da instância',users:'Admin Master',branding:'Identidade visual','general-admin':'Administração Geral',docs:'Documentação API'})[key]||'Workspace';try{
 if(key==='dashboard'){
  const {counts:c,instances}=await api('/api/dashboard');if(seq!==sequence)return;
  content.innerHTML=title('SEU CENTRO DE OPERAÇÕES','Visão geral','Conecte seus números. Integre seus sistemas. Acompanhe tudo aqui.',newButton)+connectionWarnings(instances)+`<section class="hero"><div><div class="eyebrow">CONEXÕES QUE APROXIMAM</div><h2>Seu WhatsApp, conectado ao negócio.</h2><p>Uma instância para cada conexão. Gere o QR Code e tenha sua própria URL, identificação e token para integrar.</p></div><div class="hero-art" aria-hidden="true">↗</div></section><div class="stats">${[['Instâncias',c.instances,'Canais do workspace'],['Conectadas',c.connected,'WhatsApp autenticado'],['Enviadas',c.sent,'Consulte o ACK para entrega'],['Na fila',c.queue,'Aguardando processamento']].map(([l,n,h])=>`<article class="stat"><div class="stat-label">${l}<span>↗</span></div><strong class="stat-number">${n}</strong><small>${h}</small></article>`).join('')}</div><section class="panel"><div class="panel-head"><h2>Suas instâncias</h2><a href="#instances">Ver todas →</a></div>${rows(instances)}</section><section class="panel"><div class="panel-head"><h2>Da conexão à integração</h2></div><div class="panel-body"><ol class="checklist"><li><span class="step">01</span><div><strong>Crie uma instância</strong><p>Escolha um nome para identificar seu canal.</p></div></li><li><span class="step">02</span><div><strong>Leia o QR Code</strong><p>No WhatsApp, abra Dispositivos conectados → Conectar dispositivo.</p></div></li><li><span class="step">03</span><div><strong>Use suas credenciais</strong><p>Copie a URL, o ID e o token para a integração do seu sistema.</p></div></li></ol></div></section>`;
 }else if(key==='instances'){const disabled=route.split('/')[1]==='disabled';const {instances,totals}=await api('/api/instances?state='+(disabled?'disabled':'active'));if(seq!==sequence)return;content.innerHTML=title('CANAIS DO WORKSPACE','Instâncias',disabled?'Instâncias desativadas, com dados e histórico preservados.':'Cada número com sua própria conexão e credenciais.',newButton)+`<div class="tabbar"><a href="#instances" class="${disabled?'':'selected'}">Ativas (${totals.active})</a><a href="#instances/disabled" class="${disabled?'selected':''}">Desativadas (${totals.disabled})</a></div>`+connectionWarnings(instances)+`<section class="panel"><div class="panel-head"><h2>${disabled?'Instâncias desativadas':'Instâncias ativas'}</h2><span class="badge">${instances.length} canais</span></div>${rows(instances,{disabled})}</section>`;

 }else if(key==='instance'){const data=await api(`/api/instances/${encodeURIComponent(route.split('/')[1]||'')}`);if(seq!==sequence)return;instance=data.instance;await detail();
 }else if(key==='general-admin'){if(user.role!=='admin')throw new Error('Acesso administrativo necessário.');await generalAdmin();
 }else if(key==='users'){await adminUsers();
 }else if(key==='branding'){if(!user.is_master)throw new Error('Acesso restrito ao Admin Master.');await brandSettings();
 }else if(key==='docs')docs();else location.hash='dashboard';
 if(['dashboard','instances'].includes(key))scheduleOverview();
 }catch(e){if(e.status===401)return login();content.innerHTML=title('WORKSPACE','Não foi possível carregar',esc(e.message))+'<button data-action="refresh">Tentar novamente</button>';}}
async function detail(){const i=instance;content.innerHTML=title('INSTÂNCIAS / DETALHES',esc(i.name),`<span class="cell-sub">instance${esc(i.id)}</span>`,`<div class="instance-head-actions"><a href="#instances${i.active?'':'/disabled'}">← ${i.active?'Instâncias ativas':'Instâncias desativadas'}</a><button data-action="instance-status" class="${i.active?'danger':'primary'}">${i.active?'Desativar instância':'Reativar instância'}</button></div>`)+`<div class="tabbar"><button data-tab="connection" class="${tab==='connection'?'selected':''}">Conexão e credenciais</button><button data-tab="messages" class="${tab==='messages'?'selected':''}">Mensagens</button><button data-tab="activity" class="${tab==='activity'?'selected':''}">Histórico e segurança</button></div><div id="detail-content"></div>`;const el=document.querySelector('#detail-content');
 if(tab==='activity'){if(activityViews.instance.instanceId!==i.id)activityViews.instance={page:1,filters:{},instanceId:i.id};el.innerHTML='<section class="panel" id="instance-activity"><div class="panel-body"><p>Carregando histórico…</p></div></section>';await loadActivity('instance');return;}
 if(tab==='messages'){el.innerHTML=`<section class="panel"><div class="panel-head"><h2>Histórico da API</h2><button data-action="filter">Atualizar</button></div><div class="panel-body"><div class="filterbar"><input id="message-query" placeholder="Buscar destino ou mensagem" aria-label="Busca"><select id="message-status" aria-label="Status"><option value="">Todos os status</option>${['queue','sending','sent','received','unsent','unknown'].map(s=>`<option value="${s}">${labels[s]}</option>`).join('')}</select><button data-action="filter">Filtrar</button></div></div><div id="messages-list"></div></section><p>“Enviada” indica que o envio foi processado. O ACK informa confirmação pelo servidor, dispositivo ou leitura. Envios sem confirmação não são repetidos automaticamente.</p>`;await messages();return;}
 el.innerHTML=`<section class="panel"><div class="panel-head"><h2>Nome e identificação</h2><span class="badge ${i.active?'green':''}">${i.active?'Ativa':'Desativada'}</span></div><form id="instance-form" class="panel-body"><label>Nome da instância<input name="name" required maxlength="120" value="${esc(i.name)}"></label><p>Este nome identifica a instância no painel. Alterá-lo mantém o ID, o token e a URL da integração.</p><div class="form-actions"><button class="primary">Salvar nome</button></div></form></section>${!i.active?`<section class="hero"><div><h2>Instância desativada</h2><p>Conexão, API e alertas estão suspensos. Histórico e configurações foram preservados. Reative a instância para voltar a usar.</p><p>Desativada em ${date(i.disabled_at)}.</p></div></section>`:''}<div class="detail-grid"><section class="panel"><div class="panel-head"><h2>Conexão WhatsApp</h2><div id="connection-badge">${badge(i.status)}</div></div><div class="panel-body"><div id="qr-area" class="qr-placeholder"></div><p id="connection-error" class="error"></p><div class="form-actions"><button data-action="disconnect" id="disconnect-button">Desconectar</button><button class="primary" data-action="connect" id="connect-button">Conectar / gerar QR</button></div></div></section><section class="panel"><div class="panel-head"><h2>Credenciais da API</h2></div><div class="panel-body"><dl class="meta"><div><dt>URL DA API</dt><dd>${esc(location.origin)}/instance${i.id}/</dd></div><div><dt>ID DA INSTÂNCIA</dt><dd>instance${i.id}</dd></div><div><dt>TOKEN</dt><dd class="token-row"><code id="token-text">••••••••••••••••••••••••</code><button data-action="show-token">Mostrar</button><button data-action="copy-token">Copiar</button></dd></div></dl><div class="form-actions"><button data-action="rotate">Renovar token</button></div></div></section></div><section class="panel"><div class="panel-head"><h2>Webhook</h2></div><div class="panel-body"><p class="code-note">Endereço do seu sistema que vai receber os eventos desta instância (mensagens recebidas, enviadas e confirmações de entrega), no mesmo formato do UltraMsg.</p><form id="webhook-form" class="panel-body"><label>URL do Webhook<input name="webhook_url" type="url" maxlength="2048" placeholder="https://seusistema.com/webhook/vendedor/3" value="${esc(i.webhook_url||'')}"></label><div class="form-actions"><button class="primary">Salvar webhook</button></div></form></div></section>`;await poll();}
async function poll(){const id=instance?.id;if(!id||tab!=='connection')return;try{const data=await api(`/api/instances/${id}/qr`);if(instance?.id!==id||!document.querySelector('#qr-area'))return;const el=document.querySelector('#qr-area');if(data.qr){if(el.dataset.qr!==data.qr){el.innerHTML=`<img class="qr-image" alt="QR Code para conectar o WhatsApp"><p>No celular: WhatsApp → Dispositivos conectados → Conectar dispositivo.</p>`;el.querySelector('img').src=data.qr;el.dataset.qr=data.qr;}}else{el.dataset.qr='';const messages={authenticated:['✓','WhatsApp conectado','Use as credenciais ao lado para integrar seu sistema.'],initialize:['◌','Preparando sua conexão','Aguarde o QR Code aparecer.'],retrying:['◌','Reconectando','A conexão será retomada automaticamente.'],disabled:['▣','Instância desativada','Reative a instância para conectar novamente.'],disconnecting:['◌','Encerrando sessão','Aguarde a confirmação.']};const [icon,heading,description]=messages[data.status]||['▦','Conecte seu WhatsApp','Clique em conectar para gerar seu QR Code.'];el.innerHTML=`<span>${icon}</span><h3>${heading}</h3><p>${description}</p>`;}document.querySelector('#connection-badge').innerHTML=badge(data.status);document.querySelector('#connection-error').textContent=data.error||'';document.querySelector('#connect-button').disabled=['authenticated','initialize','qr','retrying','disconnecting','disabled'].includes(data.status);document.querySelector('#disconnect-button').disabled=!['authenticated','qr'].includes(data.status);instance.status=data.status;if(data.status==='disabled'){clearTimeout(pollTimer);return;}}catch(e){if(e.status===401)return login();document.querySelector('#connection-error')?.replaceChildren(document.createTextNode(e.message));}clearTimeout(pollTimer);pollTimer=setTimeout(poll,3000);}
async function messages(){const id=instance.id;const params=new URLSearchParams({query:document.querySelector('#message-query').value,status:document.querySelector('#message-status').value});const data=await api(`/api/instances/${id}/messages?${params}`);const el=document.querySelector('#messages-list');if(!el)return;el.innerHTML=data.messages.length?`<div class="table-wrap"><table><thead><tr><th>Destino</th><th>Mensagem / anexo</th><th>Status</th><th>ACK</th><th>Data</th></tr></thead><tbody>${data.messages.map(m=>`<tr><td>${esc(m.to)}</td><td title="${esc(m.body)}">${esc(m.body.slice(0,60))}${m.media?`<br><a href="${esc(m.media)}" target="_blank" rel="noopener noreferrer">${m.type==='image'?'Abrir imagem':m.type==='audio'||m.type==='ptt'?'Abrir áudio':'Abrir anexo'}</a>`:''}</td><td>${badge(m.status)}${m.error?`<small class="message-error">${esc(m.error)}</small>`:''}</td><td>${esc(m.ack)}</td><td>${date(m.created_at)}</td></tr>`).join('')}</tbody></table></div><div class="panel-body"><p>Exibindo ${data.messages.length} de ${data.total} mensagens.</p></div>`:'<div class="empty"><div class="empty-icon">▤</div><h3>Nenhuma mensagem encontrada</h3><p>Os envios feitos pela API aparecerão aqui.</p></div>';}
function docs(){content.innerHTML=title('INTEGRAÇÃO','API compatível com UltraMsg','Mantenha os nomes dos comandos e campos. Configure a URL base, a instância e o token deste serviço.')+`<section class="panel"><div class="panel-head"><h2>Referência oficial</h2></div><div class="panel-body"><p><a href="https://docs.ultramsg.com/" target="_blank" rel="noopener noreferrer">Consultar documentação UltraMsg ↗</a></p><p>Use token em formulário/JSON ou na query de GET; Authorization: Bearer também é aceito. Retorno de envio HTTP 200 com sent: "true" significa aceitação pela fila, não entrega. Consulte ACK para acompanhar o envio.</p></div></section><section class="panel"><div class="panel-head"><h2>Comandos disponíveis</h2></div><div class="table-wrap"><table><thead><tr><th>Método</th><th>Caminho</th><th>Função</th></tr></thead><tbody>${[
['POST','messages/chat','Texto'],['POST','messages/image','Imagem URL/base64 e caption'],['POST','messages/audio','Áudio URL/base64'],['POST','messages/voice','Mensagem de voz: campo audio em OGG/Opus'],['POST','messages/video','Vídeo URL/base64 e caption'],['POST','messages/document','Documento URL/base64, filename e caption'],['POST','messages/sticker','Figurinha'],['POST','messages/link | contact | location | vcard','Link, contatos, localização e vCard'],['POST','messages/reaction | delete','Reagir ou excluir por msgId'],['GET','messages','Filtros id/referenceId/from/to/ack/status, page/limit/sort'],['GET','messages/statistics','Contadores'],['POST','messages/resendById | resendByStatus | clear','Gerenciar a fila'],['GET / POST','instance/settings','Webhook, flags e intervalo de envio'],['GET','instance/status | qr | qrCode | me','Conexão, pareamento e identificação'],['POST','instance/restart | takeover | logout | clear','Reconectar, sair e resetar'],['POST','media/upload','Upload temporário'],['GET / POST','contacts/* | chats/*','Consultar e gerenciar dados sincronizados'],['GET','groups | groups/ids | groups/group','Consultar grupos']].map(([method,path,description])=>`<tr><td>${method}</td><td><code>${path}</code></td><td>${description}</td></tr>`).join('')}</tbody></table></div></section><section class="panel"><div class="panel-head"><h2>Exemplo de envio</h2></div><div class="panel-body"><pre class="code">POST ${esc(location.origin)}/instanceSEU_ID/messages/document
Content-Type: application/x-www-form-urlencoded

token=SEU_TOKEN
to=5511999999999
filename=proposta.pdf
document=https://seu-sistema.com/proposta.pdf
caption=Sua proposta</pre><p>Codifique os campos do formulário corretamente. Mídias aceitam URL pública ou base64 (até 10.000.000 caracteres). Limites por arquivo: imagem/áudio/voz/figurinha 16 MB, documento 30 MB, vídeo 32 MB.</p></div></section><section class="panel"><div class="panel-head"><h2>Recebimento e armazenamento</h2></div><div class="panel-body"><p>Configure webhook_url e as flags webhook_message_received, webhook_message_create, webhook_message_ack e webhook_message_download_media. Eventos usam event_type, instanceId, id, referenceId e data, com identificadores @c.us.</p><p>Novos arquivos não são arquivados em bucket ou SQLite. data.media é um link temporário de uma hora, que também expira ao reiniciar. O sistema cliente deve baixar e salvar o arquivo. Arquivos enviados por base64 em fila não sobrevivem ao reinício; envios por URL podem baixar novamente da origem. URLs internas/privadas são bloqueadas.</p><p>O banco operacional mantém usuários, sessões e fila/histórico de texto/status. Contatos e conversas refletem apenas o que foi sincronizado nesta sessão, sem garantia de histórico completo. Screenshot retorna 501 porque este motor não mantém uma janela do WhatsApp Web. A equivalência integral com o serviço proprietário não foi certificada em testes com o MF Rural.</p></div></section>`;}

async function newInstance(){let owners='';if(user.role==='admin'){const data=await api('/api/users');owners=`<label>Usuário responsável<select name="owner_id">${data.users.filter(u=>u.active).map(u=>`<option value="${u.id}" ${u.id===user.id?'selected':''}>${esc(u.name)} — ${esc(u.email)}</option>`).join('')}</select></label>`;}dialog.innerHTML=`<h2>Nova instância</h2><p>Depois de criar, conecte seu número lendo o QR Code.</p><form id="new-form" class="fields"><label>Nome<input name="name" required maxlength="120" placeholder="Ex.: Atendimento" autofocus></label>${owners}<div class="form-actions"><button type="button" data-action="close">Cancelar</button><button class="primary">Criar instância</button></div></form>`;dialog.showModal();}
function newUser(){dialog.innerHTML='<h2>Novo usuário</h2><p>USER acessa suas próprias instâncias. ADMIN gerencia todas as instâncias e cria contas.</p><form id="user-form" class="fields"><label>Perfil<select name="role"><option value="user">USER</option><option value="admin">ADMIN</option></select></label><label>Nome<input name="name" required maxlength="120" autocomplete="off"></label><label>E-mail<input name="email" type="email" required maxlength="254" autocomplete="off"></label><label>Senha inicial<input name="password" type="password" required minlength="12" maxlength="256" autocomplete="new-password"><span class="field-hint">Pelo menos 12 caracteres. Compartilhe diretamente com o usuário.</span></label><div class="form-actions"><button type="button" data-action="close">Cancelar</button><button class="primary">Criar usuário</button></div></form>';dialog.showModal();}
document.addEventListener('click',async event=>{const b=event.target.closest('button');if(!b)return;try{if(b.dataset.tab){tab=b.dataset.tab;clearTimeout(pollTimer);await detail();return;}switch(b.dataset.action){case'instance-status':dialog.innerHTML=instance.active?`<h2>Desativar esta instância?</h2><p>A conexão será parada, a API ficará indisponível e os alertas serão suspensos. A instância irá para a aba Desativadas. Seus dados e histórico serão preservados.</p><p>Envios que já foram iniciados podem terminar.</p><form id="instance-status-form" data-active="false"><div class="form-actions"><button type="button" data-action="close">Cancelar</button><button class="danger">Desativar instância</button></div></form>`:`<h2>Reativar esta instância?</h2><p>Ela voltará à lista de ativas. Depois, use Conectar para retomar a conexão. Mensagens preservadas na fila poderão ser retomadas ao conectar.</p><form id="instance-status-form" data-active="true"><div class="form-actions"><button type="button" data-action="close">Cancelar</button><button class="primary">Reativar instância</button></div></form>`;dialog.showModal();break;case'activity-page':activityViews[b.dataset.scope].page=Number(b.dataset.page);await loadActivity(b.dataset.scope);break;case'activity-reset':activityViews[b.dataset.scope].page=1;activityViews[b.dataset.scope].filters={};await loadActivity(b.dataset.scope);break;case'activity-refresh':await loadActivity(b.dataset.scope);break;case'history-page':incidentPage=Number(b.dataset.page);await loadIncidentHistory();break;case'history-clear':incidentFilters={instance_id:'',status:'all',email_status:'all',from:'',to:'',kind:'confirmed'};incidentPage=1;await loadIncidentHistory();break;case'incident-detail':await openIncident(b.dataset.id);break;case'incident-more':b.disabled=true;try{await loadIncidentEvents(b.dataset.id,Number(b.dataset.page));}finally{b.disabled=false;}break;case'test-alert-email':b.disabled=true;try{await api('/api/general-admin/test-email',{method:'POST',body:'{}'});toast('E-mail de teste enviado. Confira a caixa de entrada e o spam.');}finally{await generalAdmin();}break;case'new':await newInstance();break;case'new-user':newUser();break;case'edit-user':editUser(b.dataset.id);break;case'close':dialog.close();break;case'logout':await api('/api/auth/logout',{method:'POST',body:'{}'});login();break;case'refresh':await render();break;case'filter':await messages();break;case'connect':b.disabled=true;await api(`/api/instances/${instance.id}/connect`,{method:'POST',body:'{}'});await poll();break;case'disconnect':dialog.innerHTML='<h2>Desconectar WhatsApp?</h2><p>A sessão será encerrada. Você precisará ler um novo QR para conectar novamente. Mensagens na fila serão mantidas.</p><form id="disconnect-form"><div class="form-actions"><button type="button" data-action="close">Cancelar</button><button class="primary">Desconectar</button></div></form>';dialog.showModal();break;case'show-token':{const show=b.textContent==='Mostrar';if(show)await api(`/api/instances/${instance.id}/credential-access`,{method:'POST',body:JSON.stringify({action:'reveal'})});document.querySelector('#token-text').textContent=show?instance.token:'••••••••••••••••••••••••';b.textContent=show?'Ocultar':'Mostrar';break;}case'copy-token':await api(`/api/instances/${instance.id}/credential-access`,{method:'POST',body:JSON.stringify({action:'copy'})});await navigator.clipboard.writeText(instance.token);toast('Token copiado.');break;case'rotate':dialog.innerHTML='<h2>Renovar token?</h2><p>O token atual deixará de funcionar. Atualize a credencial no seu sistema após a troca.</p><form id="rotate-form"><div class="form-actions"><button type="button" data-action="close">Cancelar</button><button class="primary">Renovar token</button></div></form>';dialog.showModal();break;}}catch(e){if(e.status===401)return login();toast(e.message);if(b.dataset.action==='connect')b.disabled=false;}});
document.addEventListener('submit',async event=>{const f=event.target;event.preventDefault();const data=Object.fromEntries(new FormData(f)),button=f.querySelector('button:not([type="button"])');if(button)button.disabled=true;try{switch(f.id){case'instance-status-form':await api(`/api/instances/${instance.id}/lifecycle`,{method:'POST',body:JSON.stringify({active:f.dataset.active==='true'})});dialog.close();toast(f.dataset.active==='true'?'Instância reativada. Use Conectar quando quiser retomar.':'Instância desativada. Histórico preservado.');await render();break;case'activity-filter-global':case'activity-filter-instance':{const scope=f.dataset.scope;activityViews[scope].filters={...data};activityViews[scope].page=1;await loadActivity(scope);break;}case'incident-filter-form':incidentFilters={...data};incidentPage=1;await loadIncidentHistory();break;case'general-admin-form':await api('/api/general-admin',{method:'PATCH',body:JSON.stringify({alert_email:data.alert_email})});toast('E-mail de alerta salvo. Alteração registrada no log.');await generalAdmin();break;case'login-form':await api('/api/auth/login',{method:'POST',body:JSON.stringify(data)});location.hash='dashboard';await start();break;case'new-form':{const result=await api('/api/instances',{method:'POST',body:JSON.stringify(data)});dialog.close();tab='connection';location.hash=`instance/${result.instance.id}`;toast('Instância criada.');break;}case'user-form':await api('/api/users',{method:'POST',body:JSON.stringify(data)});dialog.close();toast('Usuário criado.');await render();break;case'edit-user-form':{if(!data.password)delete data.password;data.active=f.elements.active.checked;await api(`/api/users/${f.dataset.id}`,{method:'PATCH',body:JSON.stringify(data)});dialog.close();toast('Acesso atualizado.');await start();break;}case'branding-form':await saveBranding(f);break;case'instance-form':await api(`/api/instances/${instance.id}`,{method:'PATCH',body:JSON.stringify({name:data.name})});toast('Nome atualizado.');await render();break;case'webhook-form':await api(`/api/instances/${instance.id}`,{method:'PATCH',body:JSON.stringify({webhook_url:data.webhook_url})});toast('Webhook atualizado.');await render();break;case'rotate-form':await api(`/api/instances/${instance.id}/token`,{method:'POST',body:'{}'});dialog.close();toast('Token renovado.');await render();break;case'disconnect-form':await api(`/api/instances/${instance.id}/disconnect`,{method:'POST',body:'{}'});dialog.close();await poll();toast('WhatsApp desconectado.');break;}}catch(e){if(f.id==='login-form')document.querySelector('#login-error').textContent=e.message;else if(e.status===401)login();else toast(e.message);}finally{if(button)button.disabled=false;}});
window.addEventListener('hashchange',()=>{tab='connection';render();});start();

function brandMarkup(context){const src=branding[context];return src?`<img class="brand-logo" src="${esc(src)}" alt="${esc(branding.name)}">`:`<span class="brand-icon">W</span><span class="brand-name">${esc(branding.name)}<small>CONEXÕES WHATSAPP</small></span>`;}
function applyBranding(){document.title=branding.name;document.querySelectorAll('[data-brand]').forEach(el=>{el.innerHTML=brandMarkup(el.dataset.brand);el.setAttribute('aria-label',branding.name);});document.querySelectorAll('[data-brand-name]').forEach(el=>el.textContent=branding.name);const icon=document.querySelector('#app-favicon');icon.type=branding.favicon?'image/png':'image/svg+xml';icon.href=branding.favicon||'/favicon.svg';}
const adminTabs=active=>`<div class="tabbar"><a class="${active==='users'?'selected':''}" href="#users">Usuários e acessos</a>${user.is_master?`<a class="${active==='branding'?'selected':''}" href="#branding">Identidade visual</a>`:''}</div>`;
async function adminUsers(){const {users}=await api('/api/users');managedUsers=users;content.innerHTML=title('ADMINISTRAÇÃO','Administração','Controle os acessos e a identidade da sua plataforma.','<button class="primary" data-action="new-user">＋ Novo usuário</button>')+adminTabs('users')+`<section class="panel"><div class="panel-head"><h2>Usuários e acessos</h2><span class="badge">${users.length} usuários</span></div><div class="table-wrap"><table><thead><tr><th>Nome</th><th>E-mail</th><th>Perfil</th><th>Acesso</th><th></th></tr></thead><tbody>${users.map(u=>`<tr><td>${esc(u.name)}</td><td>${esc(u.email)}</td><td>${u.is_master?'Admin Master':u.role==='admin'?'ADMIN':'USER'}</td><td><span class="badge ${u.active?'green':''}">${u.active?'Ativo':'Bloqueado'}</span></td><td>${!u.is_master||u.id===user.id?`<button data-action="edit-user" data-id="${u.id}">Gerenciar acesso</button>`:'Conta protegida'}</td></tr>`).join('')}</tbody></table></div></section><p>O bloqueio encerra os acessos ao painel e à API e pausa novos envios da fila. Um envio já em andamento pode ser concluído. As instâncias e as sessões WhatsApp são preservadas.</p>`;}
function editUser(id){const u=managedUsers.find(u=>u.id===id);if(!u||(u.is_master&&u.id!==user.id))return;dialog.innerHTML=`<h2>Gerenciar acesso</h2><p>${u.is_master?'Conta Admin Master. Ao trocar sua senha ou e-mail, entre novamente.':'Edite os dados, redefina a senha ou bloqueie o acesso.'}</p><form id="edit-user-form" data-id="${u.id}" class="fields">${u.is_master?'':`<label>Perfil<select name="role"><option value="user" ${u.role==='user'?'selected':''}>USER</option><option value="admin" ${u.role==='admin'?'selected':''}>ADMIN</option></select></label>`}<label>Nome<input name="name" required maxlength="120" value="${esc(u.name)}"></label><label>E-mail<input name="email" type="email" required maxlength="254" value="${esc(u.email)}"></label><label>Nova senha<input name="password" type="password" minlength="12" maxlength="256" autocomplete="new-password"><span class="field-hint">Deixe em branco para manter a senha atual.</span></label><label class="check-label"><input type="checkbox" name="active" ${u.active?'checked':''} ${u.is_master?'disabled':''}>Acesso ativo</label><div class="form-actions"><button type="button" data-action="close">Cancelar</button><button class="primary">Salvar acesso</button></div></form>`;dialog.showModal();}
async function brandSettings(){branding=(await api('/api/branding')).branding;applyBranding();content.innerHTML=title('ADMIN MASTER','Identidade visual','Sua marca na tela de login, no painel e na aba do navegador.')+adminTabs('branding')+`<form id="branding-form"><section class="panel"><div class="panel-head"><h2>Nome da aplicação</h2></div><div class="panel-body"><label>Nome do app<input name="name" required maxlength="60" value="${esc(branding.name)}"></label></div></section><div class="brand-grid">${[['positive','Logo positiva','Para fundos claros, como a tela de login.'],['negative','Logo negativa','Para fundos escuros, como o menu lateral.'],['favicon','Favicon','Ícone da aba do navegador. Prefira uma imagem quadrada.']].map(([slot,label,hint])=>`<section class="panel"><div class="panel-head"><h2>${label}</h2></div><div class="panel-body"><div class="asset-preview ${slot==='negative'?'dark':''}" data-preview="${slot}">${branding[slot]?`<img src="${esc(branding[slot])}" alt="${label}">`:'<span>Nenhuma imagem definida</span>'}</div><label>${label}<input type="file" name="${slot}" accept="image/png,image/jpeg,image/webp"><span class="field-hint">${hint}</span></label><label class="check-label"><input type="checkbox" name="remove_${slot}">Remover imagem atual</label></div></section>`).join('')}</div><p>PNG, JPG ou WebP, até 1 MB por imagem. Logos com fundo transparente funcionam melhor. Sem logo, o nome do app será exibido.</p><div class="form-actions"><button class="primary">Salvar identidade visual</button></div></form>`;}
const fileData=file=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('Não foi possível ler a imagem.'));reader.readAsDataURL(file);});
async function saveBranding(form){const input={name:form.elements.name.value};for(const slot of ['positive','negative','favicon']){const file=form.elements[slot].files[0];if(form.elements[`remove_${slot}`].checked)input[slot]=null;else if(file){if(file.size>1024*1024)throw new Error('Cada imagem pode ter até 1 MB.');input[slot]=await fileData(file);}}branding=(await api('/api/branding',{method:'PATCH',body:JSON.stringify(input)})).branding;applyBranding();await brandSettings();toast('Identidade visual atualizada.');}
document.addEventListener('change',async event=>{const el=event.target;if(el.type!=='file'||!el.closest('#branding-form'))return;const preview=document.querySelector(`[data-preview="${el.name}"]`),file=el.files[0];if(!file)return;if(file.size>1024*1024){el.value='';toast('Cada imagem pode ter até 1 MB.');return;}const img=document.createElement('img');img.alt='Prévia da imagem selecionada';img.src=await fileData(file);preview.replaceChildren(img);el.form.elements[`remove_${el.name}`].checked=false;});

function connectionWarnings(items){const affected=items.filter(i=>i.connection_alert);if(!affected.length)return '';return `<section class="connection-warning" role="alert"><div class="warning-icon" aria-hidden="true">!</div><div><h2>${affected.length===1?'Uma instância perdeu a conexão':affected.length+' instâncias perderam a conexão'}</h2><p>Verifique os canais abaixo. Eles já foram conectados e precisam de atenção para retomar os envios.</p><ul>${affected.map(i=>`<li><a href="#instance/${i.id}">${esc(i.name)} · ${esc(i.phone||'Número não informado')}</a><span>Desde ${date(i.connection_alert.opened_at)}</span></li>`).join('')}</ul></div></section>`;}
function scheduleOverview(){clearTimeout(pollTimer);const refresh=()=>{if(!user)return;if(!['dashboard','instances',''].includes(location.hash.slice(1).split('/')[0]))return;if(dialog.open){pollTimer=setTimeout(refresh,10000);return;}void render();};pollTimer=setTimeout(refresh,10000);}
const notificationLabels={pending:'Na fila',blocked:'Aguardando configuração',sending:'Enviando',sent:'Enviado',error:'Falhou · nova tentativa programada',failed:'Falha após 5 tentativas',unknown:'Envio sem confirmação',cancelled:'Cancelado após reconectar'};
const auditLabels={alert_email_updated:'E-mail de alerta alterado',alert_email_test_requested:'Teste de e-mail solicitado',alert_email_test_sent:'Teste de e-mail enviado',alert_email_test_failed:'Teste de e-mail falhou'};
function auditValue(raw){try{const v=JSON.parse(raw);return v.alert_email||v.recipient||'—';}catch{return '—';}}
async function generalAdmin(){
 const {settings,smtp_ready,audit}=await api('/api/general-admin');
 content.innerHTML=title('ADMINISTRAÇÃO GERAL','Alertas de conexão','Configuração compartilhada entre todos os administradores. Cada alteração fica registrada.','<button data-action="refresh">Atualizar histórico</button>')+`
 <section class="panel"><div class="panel-head"><h2>E-mail de alerta</h2><span class="badge ${smtp_ready?'green':'red'}">${smtp_ready?'Envio configurado':'SMTP pendente'}</span></div><form id="general-admin-form" class="panel-body fields"><p>Receba um alerta quando uma instância que já foi conectada perder a conexão. Uma mesma queda gera um único alerta; uma nova queda após reconectar gera outro.</p><label>Enviar alertas para<input name="alert_email" type="email" required maxlength="254" autocomplete="email" placeholder="ti@suaempresa.com.br" value="${esc(settings.alert_email)}"><span class="field-hint">Um único endereço. Você pode usar o e-mail de um grupo de distribuição da equipe.</span></label><div class="form-actions"><button type="button" data-action="test-alert-email" ${!settings.alert_email||!smtp_ready?'disabled':''}>Enviar e-mail de teste</button><button class="primary">Salvar e-mail de alerta</button></div><p>O teste usa o endereço que já foi salvo. Interrupções recuperáveis aguardam 60 segundos antes de gerar queda e e-mail. Sessão encerrada, desconexão explícita ou novo QR exigido geram alerta imediato. A instância com queda confirmada fica vermelha até reconectar.</p>${!settings.alert_email?'<p class="error">Cadastre um endereço para ativar os alertas por e-mail.</p>':''}${!smtp_ready?'<p class="error">O envio de e-mails ainda precisa ser configurado no servidor.</p>':''}</form></section>
 <section class="panel"><div class="panel-head"><h2>Histórico de alterações</h2><span class="badge">Últimos 100 registros</span></div>${audit.length?`<div class="table-wrap"><table><thead><tr><th>Quando</th><th>Administrador</th><th>Ação</th><th>Anterior</th><th>Novo / destinatário</th></tr></thead><tbody>${audit.map(a=>`<tr><td>${date(a.created_at)}</td><td>${esc(a.actor_name)}<span class="cell-sub">${esc(a.actor_email)}</span></td><td>${esc(auditLabels[a.action]||a.action)}</td><td>${esc(auditValue(a.before_value))}</td><td>${esc(auditValue(a.after_value))}</td></tr>`).join('')}</tbody></table></div>`:'<div class="panel-body"><p>Nenhuma alteração registrada ainda.</p></div>'}</section>
 <section class="panel" id="global-activity"><div class="panel-body"><p>Carregando log de segurança…</p></div></section><section class="panel" id="incident-history"><div class="panel-head"><h2>Histórico de quedas</h2></div><div class="panel-body"><p>Carregando ocorrências…</p></div></section>`;
 await Promise.all([loadIncidentHistory(),loadActivity('global')]);

}

const historyDate=v=>v?new Date(v).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'}):'Não registrado';
const outageDuration=seconds=>{if(!Number.isFinite(seconds))return 'Não registrado';const n=Math.max(0,seconds),days=Math.floor(n/86400),hours=Math.floor(n%86400/3600),minutes=Math.floor(n%3600/60);return [days?days+'d':'',hours?hours+'h':'',minutes?minutes+'min':'',!days&&!hours&&!minutes?Math.floor(n)+'s':''].filter(Boolean).join(' ');};
const sourceLabels={whatsapp:'WhatsApp',manual_disconnect:'Desconexão pelo painel/API',startup_reconcile:'Verificação após reiniciar',transport_start:'Falha ao iniciar conexão',unknown:'Não registrada'};
const mailBadge=i=>`<span class="badge ${i.notification_status==='sent'?'green':['failed','error','unknown'].includes(i.notification_status)?'red':''}">${esc(i.notification_status==='sent'?'✓ E-mail enviado ao SES':notificationLabels[i.notification_status]||i.notification_status)}</span>`;
async function loadIncidentHistory(){
 const request=++historyRequest,params=new URLSearchParams({...incidentFilters,page:incidentPage,limit:25});
 let data;try{data=await api('/api/general-admin/incidents?'+params);}catch(e){if(e.status===401)return login();const target=document.querySelector('#incident-history');if(target&&request===historyRequest)target.innerHTML=`<div class="panel-head"><h2>Histórico de quedas</h2></div><div class="panel-body"><p class="error">${esc(e.message)}</p><button data-action="history-clear">Limpar filtros e tentar novamente</button></div>`;return;}
 const el=document.querySelector('#incident-history');if(!el||request!==historyRequest)return;
 const selected=(key,value)=>incidentFilters[key]===value?'selected':'';
 const sum=data.summary;
 el.innerHTML=`<div class="panel-head"><div><h2>Histórico de quedas</h2><p>Quedas confirmadas após 60s ou que exigem intervenção. Reconexões breves anteriores ficam no filtro próprio. Horários de Brasília.</p></div><span class="badge">${data.total} ocorrência(s)</span></div>
 <form id="incident-filter-form" class="incident-filters"><label>Classificação<select name="kind">${[['confirmed','Quedas confirmadas'],['transient','Reconexões breves (anteriores)'],['all','Todos os registros']].map(([key,label])=>`<option value="${key}" ${selected('kind',key)}>${label}</option>`).join('')}</select></label><label>Instância<select name="instance_id"><option value="">Todas as instâncias</option>${data.instances.map(i=>`<option value="${esc(i.id)}" ${selected('instance_id',i.id)}>${esc(i.name)} · ${esc(i.id)}</option>`).join('')}</select></label><label>De<input name="from" type="date" value="${esc(incidentFilters.from)}"></label><label>Até<input name="to" type="date" value="${esc(incidentFilters.to)}"></label><label>Conexão<select name="status">${[['all','Todas'],['open','Em aberto'],['resolved','Reconectadas'],['deactivated','Encerradas por desativação']].map(([key,label])=>`<option value="${key}" ${selected('status',key)}>${label}</option>`).join('')}</select></label><label>E-mail<select name="email_status"><option value="all">Todos os estados</option>${Object.entries(notificationLabels).map(([key,label])=>`<option value="${key}" ${selected('email_status',key)}>${esc(label)}</option>`).join('')}</select></label><div class="incident-filter-actions"><button class="primary">Filtrar</button><button type="button" data-action="history-clear">Limpar</button></div></form>
 <div class="incident-totals">${[['Ocorrências no filtro',sum.total],['Em aberto',sum.open],['Reconectadas',sum.resolved],['E-mails enviados',sum.emails_sent],['E-mails com falha ou dúvida',sum.email_issues],['Encerradas por desativação',sum.deactivated]].map(([label,value])=>`<div><strong>${value}</strong><span>${label}</span></div>`).join('')}</div>
 ${data.incidents.length?`<div class="table-wrap"><table><thead><tr><th>Instância / responsável</th><th>Queda e duração</th><th>Motivo</th><th>Alerta por e-mail</th><th></th></tr></thead><tbody>${data.incidents.map(i=>`<tr class="${i.resolved_at?'':'instance-danger'}"><td><a class="cell-name" href="#instance/${esc(i.instance_id)}">${esc(i.instance_name||i.instance_id)}</a><span class="cell-sub">${esc(i.instance_phone||'Número não registrado')} · ${esc(i.instance_id)}</span><span class="cell-sub">${esc(i.owner_name||'Responsável não registrado')}</span></td><td>${historyDate(i.opened_at)}<span class="cell-sub">${i.resolution_reason==='deactivated'?'Desativada em '+historyDate(i.resolved_at):i.resolved_at?'Reconectada em '+historyDate(i.resolved_at):'⚠ Continua desconectada'}</span><strong class="cell-sub">${outageDuration(i.duration_seconds)} ${i.resolution_reason==='deactivated'?'até desativar':i.resolved_at?'sem conexão':'até agora'}</strong></td><td>${i.outage_kind==='transient'?'<span class="badge amber">Reconexão breve · registro anterior</span><br>':''}${esc(i.reason)}<span class="cell-sub">${esc(sourceLabels[i.source]||i.source)}${i.disconnect_code!==null?' · Código '+esc(i.disconnect_code):''}</span></td><td>${mailBadge(i)}<span class="cell-sub">${esc(i.recipient||'Destinatário ainda não registrado')}</span><span class="cell-sub">${i.email_sent_at?historyDate(i.email_sent_at):i.notification_status==='sent'?'Horário de envio não registrado':''} · ${i.attempts} tentativa(s)</span></td><td><button data-action="incident-detail" data-id="${i.id}">Ver detalhes</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><h3>Nenhuma queda neste filtro</h3><p>As próximas ocorrências aparecerão aqui, sem apagar as anteriores.</p></div>'}
 <div class="incident-pagination"><span>Página ${data.page} de ${Math.max(1,data.pages)} · ${data.total} registro(s)</span><div><button data-action="history-page" data-page="${data.page-1}" ${data.page<=1?'disabled':''}>← Anterior</button><button data-action="history-page" data-page="${data.page+1}" ${data.page>=data.pages?'disabled':''}>Próxima →</button></div></div>
 ${data.total?`<div class="incident-patterns"><h3>Recorrências nos registros filtrados</h3><p>Frequência observada; não é uma conclusão sobre a causa das quedas. Datas filtram o início da ocorrência.</p><div class="pattern-grid"><section><h4>Instâncias com mais quedas</h4><ul>${data.patterns.by_instance.map(p=>`<li><span>${esc(p.instance_name||p.instance_id)}</span><b>${p.count}</b></li>`).join('')}</ul></section><section><h4>Horários mais frequentes</h4><ul>${data.patterns.by_hour.map(p=>`<li><span>${esc(p.hour)}h–${esc(p.hour)}h59 · Brasília</span><b>${p.count}</b></li>`).join('')}</ul></section><section><h4>Motivos mais frequentes</h4><ul>${data.patterns.by_reason.map(p=>`<li><span>${esc(p.reason)}${p.disconnect_code!==null?' · Código '+esc(p.disconnect_code):''}</span><b>${p.count}</b></li>`).join('')}</ul></section></div></div>`:''}`;
}
const eventLabels={monitoring_disabled:'Monitoramento encerrado por desativação da instância',outage_opened:'Interrupção detectada',outage_confirmed:'Queda confirmada após a tolerância de reconexão',connection_update:'Atualização da conexão',reconnected:'Conexão restabelecida',email_attempt:'Tentativa de envio de e-mail',email_sent:'E-mail aceito pelo SES',email_failed:'Falha no envio do e-mail',email_blocked:'E-mail aguardando configuração',email_cancelled:'Envio pendente cancelado',email_unknown:'Envio sem confirmação após reinício',email_requeued:'E-mail recolocado na fila'};
function eventRows(events){return events.map(e=>{const d=e.details,parts=[d.reason,d.status?labels[d.status]||d.status:'',d.source?sourceLabels[d.source]||d.source:'',d.code!==null&&d.code!==undefined?'Código: '+d.code:'',d.reconnect_attempt?'Tentativa automática: '+d.reconnect_attempt:'',d.recipient?'Para: '+d.recipient:'',d.attempt?'Envio nº '+d.attempt:'',d.message_id?'ID SMTP: '+d.message_id:'',d.actor_name?'Por: '+d.actor_name:'',d.will_retry===false?'Sem novas tentativas automáticas':''];return `<li><time>${historyDate(e.created_at)}</time><div><strong>${esc(eventLabels[e.kind]||e.kind)}</strong><p>${esc(parts.filter(Boolean).join(' · '))}</p></div></li>`;}).join('');}
function moreIncidentEvents(data){return data.page<data.pages?`<button data-action="incident-more" data-id="${data.incident.id}" data-page="${data.page+1}">Carregar mais eventos (${data.page*data.limit} de ${data.total_events})</button>`:`<p>${data.total_events} evento(s) registrado(s).</p>`;}
async function openIncident(id){
 const request=++detailRequest,data=await api('/api/general-admin/incidents/'+encodeURIComponent(id)+'?limit=100');if(request!==detailRequest)return;
 const i=data.incident;
 dialog.innerHTML=`<div class="incident-detail" data-incident="${i.id}"><div class="panel-head"><div><h2>Queda #${i.id} · ${esc(i.instance_name||i.instance_id)}</h2><p>${esc(i.instance_phone||'Número não registrado')} · ${esc(i.instance_id)} · ${esc(i.owner_name||'Responsável não registrado')}</p></div><button data-action="close">Fechar</button></div><div class="panel-body">
 ${i.outage_kind==='transient'?'<p class="incident-legacy">Reconexão breve anterior à tolerância de 60s. O registro e o e-mail enviado foram preservados, mas não contam como queda confirmada no filtro padrão.</p>':''}<p><span class="badge ${i.resolved_at?'green':'red'}">${i.resolution_reason==='deactivated'?'Encerrada por desativação':i.resolved_at?'Conexão restabelecida':'⚠ Em aberto'}</span> ${mailBadge(i)}</p>
 ${i.capture_version==='legacy'?'<p class="incident-legacy">Registro anterior ao histórico detalhado. Nome, número e responsável foram recuperados do cadastro disponível; horários técnicos e eventos antigos não foram inventados.</p>':''}
 <dl class="incident-facts">${[['Queda',historyDate(i.opened_at)],['Recuperação / encerramento',i.resolution_reason==='deactivated'?'Desativada em '+historyDate(i.resolved_at):i.resolved_at?historyDate(i.resolved_at):'Ainda não reconectou'],['Duração sem conexão',outageDuration(i.duration_seconds)],['Última conexão antes da queda',historyDate(i.last_connected_at)],['Origem',sourceLabels[i.source]||i.source],['Código técnico',i.disconnect_code??'Não fornecido'],['Tentativas automáticas de reconexão',i.capture_version==='legacy'?'Não registradas':i.reconnect_attempts],['Último evento',historyDate(i.last_event_at)],['Versão do código',i.app_commit||'Não informada'],['Implantação',i.deployment_id||'Não informada']].map(([label,value])=>`<div><dt>${label}</dt><dd>${esc(value)}</dd></div>`).join('')}</dl>
 <h3>Motivo registrado</h3><p>${esc(i.reason)}</p><h3 class="incident-section-title">Alerta por e-mail</h3><dl class="incident-facts">${[['Situação',i.notification_status==='sent'?'Enviado ao SES (aceito pelo provedor)':notificationLabels[i.notification_status]||i.notification_status],['Destinatário',i.recipient||'Não registrado'],['Horário do envio',historyDate(i.email_sent_at)],['Tentativas no ciclo atual de envio',i.attempts],['Último erro',i.last_error||'Nenhum registrado'],['ID da mensagem SMTP',i.message_id||'Não registrado'],['Próxima tentativa',i.notification_status==='error'&&i.next_attempt_at?historyDate(i.next_attempt_at):'—']].map(([label,value])=>`<div><dt>${label}</dt><dd>${esc(value)}</dd></div>`).join('')}</dl><p>O estado enviado confirma aceitação pelo provedor SMTP; a entrega na caixa de entrada deve ser conferida no destinatário.</p>
 <h3 class="incident-section-title">Linha do tempo · horário de Brasília</h3><ol class="incident-timeline" id="incident-events">${eventRows(data.events)}</ol><div id="incident-more">${moreIncidentEvents(data)}</div><div class="form-actions"><button data-action="incident-detail" data-id="${i.id}">Atualizar detalhes</button><button data-action="close">Fechar</button></div></div></div>`;
 if(!dialog.open)dialog.showModal();
}
async function loadIncidentEvents(id,page){const data=await api('/api/general-admin/incidents/'+encodeURIComponent(id)+'?limit=100&page='+page);if(dialog.querySelector('[data-incident]')?.dataset.incident!==String(id))return;dialog.querySelector('#incident-events').insertAdjacentHTML('beforeend',eventRows(data.events));dialog.querySelector('#incident-more').innerHTML=moreIncidentEvents(data);}

const activityLabels={instance_deactivated:'Instância desativada',instance_reactivated:'Instância reativada',instance_created:'Instância criada',instance_viewed:'Instância acessada (inclui credenciais)',instance_updated:'Configuração da instância alterada',token_rotated:'Token renovado',token_reveal_requested:'Solicitou exibir o token',token_copy_requested:'Solicitou copiar o token',connection_requested:'Solicitação de conexão / QR',disconnection_requested:'Solicitação de desconexão',connection_established:'Conexão confirmada',connection_lost:'Conexão perdida / encerrada',connection_retry:'Tentativa automática de reconexão',connection_qr:'QR Code disponível',connection_number_changed:'Número conectado alterado',instance_access_denied:'Acesso à instância negado',messages_viewed:'Histórico de mensagens consultado',alert_email_updated:'E-mail de alerta alterado',alert_email_test:'Teste de e-mail solicitado',alert_email_test_requested:'Teste de e-mail solicitado (anterior)',alert_email_test_sent:'Teste de e-mail enviado (anterior)',alert_email_test_failed:'Teste de e-mail falhou (anterior)'};
const activityOutcome={requested:'Solicitação registrada',success:'Concluída',failed:'Falhou',observed:'Evento registrado',denied:'Acesso negado'};
const activityKinds={user:'Usuário autenticado',api:'Integração (token)',system:'Sistema automático',legacy:'Registro anterior'};
function activityTitle(event){if(event.action==='instance_updated'&&event.outcome==='success'){const changes=[];if(event.before.name!==event.after.name)changes.push('nome');if(event.before.webhook?.fingerprint!==event.after.webhook?.fingerprint||event.before.webhook?.configured!==event.after.webhook?.configured)changes.push('webhook');return changes.length?'Alterou '+changes.join(' e '):'Salvou configuração da instância';}return activityLabels[event.action]||(event.action.startsWith('api.')?'API · '+event.action.slice(4):event.action);}
function activityDetails(event){const changed=Object.keys(event.before).length||Object.keys(event.after).length;const details=Object.keys(event.details).length;return `<details class="activity-detail"><summary>Ver registro</summary>${event.details.historical?'<p class="field-hint">Registro anterior à auditoria detalhada. A autoria ausente não foi atribuída ao responsável atual.</p>':''}${changed?`<div class="activity-diff"><div><strong>Antes</strong><pre>${esc(JSON.stringify(event.before,null,2))}</pre></div><div><strong>Depois</strong><pre>${esc(JSON.stringify(event.after,null,2))}</pre></div></div>`:''}${details?`<strong>Contexto</strong><pre>${esc(JSON.stringify(event.details,null,2))}</pre>`:''}${event.request_id?`<p>ID de correlação: <code>${esc(event.request_id)}</code></p>`:''}${event.peer_ip?`<p>IP da conexão com o servidor (pode ser proxy): ${esc(event.peer_ip)}</p>`:''}<p>Origem: ${esc(event.source)}</p></details>`;}
async function loadActivity(scope){
 if(!['global','instance'].includes(scope))return;
 const state=activityViews[scope],request=++activitySequence[scope],id=state.instanceId;
 const endpoint=scope==='global'?'/api/general-admin/activity':`/api/instances/${id}/activity`;
 let data;try{data=await api(endpoint+'?'+new URLSearchParams({...state.filters,page:state.page,limit:25}));}catch(e){if(e.status===401)return login();const target=document.querySelector(scope==='global'?'#global-activity':'#instance-activity');if(target)target.innerHTML=`<div class="panel-body"><h2>Histórico de atividades</h2><p class="error">${esc(e.message)}</p><button data-action="activity-reset" data-scope="${scope}">Limpar filtros e tentar novamente</button></div>`;return;}
 const target=document.querySelector(scope==='global'?'#global-activity':'#instance-activity');if(!target||request!==activitySequence[scope]||(scope==='instance'&&instance?.id!==id))return;
 const chosen=(key,value)=>state.filters[key]===value?'selected':'';
 target.innerHTML=`<div class="panel-head"><div><h2>${scope==='global'?'Log de atividades e segurança':'Histórico e segurança da instância'}</h2><p>Horários de Brasília. Solicitações e confirmações do WhatsApp são registradas separadamente.</p></div><button data-action="activity-refresh" data-scope="${scope}">Atualizar log</button></div>
 <form id="activity-filter-${scope}" data-scope="${scope}" class="activity-filters">${scope==='global'?`<label>Instância<select name="instance_id"><option value="">Todas / configuração geral</option>${data.instances.map(i=>`<option value="${esc(i.id)}" ${chosen('instance_id',i.id)}>${esc(i.name||i.id)}</option>`).join('')}</select></label>`:''}<label>Quem executou<select name="actor_id"><option value="">Todos</option>${data.actors.map(a=>`<option value="${esc(a.id)}" ${chosen('actor_id',a.id)}>${esc(a.name)}${a.email?' · '+esc(a.email):''}</option>`).join('')}</select></label><label>Ação<select name="action"><option value="">Todas</option>${data.actions.map(action=>`<option value="${esc(action)}" ${chosen('action',action)}>${esc(activityLabels[action]||(action.startsWith('api.')?'API · '+action.slice(4):action))}</option>`).join('')}</select></label><label>Resultado<select name="outcome"><option value="">Todos</option>${Object.entries(activityOutcome).map(([key,label])=>`<option value="${key}" ${chosen('outcome',key)}>${label}</option>`).join('')}</select></label><label>Origem da autoria<select name="actor_kind"><option value="">Todas</option>${Object.entries(activityKinds).map(([key,label])=>`<option value="${key}" ${chosen('actor_kind',key)}>${label}</option>`).join('')}</select></label><label>De<input type="date" name="from" value="${esc(state.filters.from||'')}"></label><label>Até<input type="date" name="to" value="${esc(state.filters.to||'')}"></label><div class="incident-filter-actions"><button class="primary">Filtrar</button><button type="button" data-action="activity-reset" data-scope="${scope}">Limpar</button></div></form>
 ${data.events.length?`<div class="table-wrap"><table class="activity-table"><thead><tr><th>Quando</th><th>Quem</th>${scope==='global'?'<th>Instância</th>':''}<th>Ação / resultado</th><th>Detalhes</th></tr></thead><tbody>${data.events.map(e=>`<tr><td>${historyDate(e.created_at)}<span class="cell-sub">Registro #${e.id}</span></td><td><strong>${esc(e.actor_name)}</strong><span class="cell-sub">${esc(e.actor_email)}</span>${e.details.attribution==='linked_to_connection_request'?'<span class="cell-sub">Vinculado à solicitação deste usuário</span>':''}<span class="badge">${esc(activityKinds[e.actor_kind]||e.actor_kind)}${e.actor_role==='admin'?' · ADMIN':''}</span></td>${scope==='global'?`<td>${e.instance_id?`<a href="#instance/${esc(e.instance_id)}">${esc(e.instance_name||e.instance_id)}</a><span class="cell-sub">${esc(e.instance_id)}</span>`:'Administração Geral'}</td>`:''}<td>${esc(activityTitle(e))}<span class="cell-sub"><span class="badge ${e.outcome==='success'?'green':['failed','denied'].includes(e.outcome)?'red':''}">${activityOutcome[e.outcome]||esc(e.outcome)}</span></span></td><td>${activityDetails(e)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><h3>Nenhum registro neste filtro</h3><p>As atividades ficam salvas após sair, reconectar ou renovar o token.</p></div>'}
 <div class="incident-pagination"><span>Página ${data.page} de ${Math.max(1,data.pages)} · ${data.total} registro(s)</span><div><button data-action="activity-page" data-scope="${scope}" data-page="${data.page-1}" ${data.page<=1?'disabled':''}>← Anterior</button><button data-action="activity-page" data-scope="${scope}" data-page="${data.page+1}" ${data.page>=data.pages?'disabled':''}>Próxima →</button></div></div><div class="panel-body"><p>Senhas, QR Codes e valores de tokens não são gravados. Webhooks mostram apenas a origem e uma impressão digital para identificar trocas, sem expor o endereço completo.</p></div>`;
}
